"""Payment capture with retries."""

import time

MAX_ATTEMPTS = 3


class PaymentError(Exception):
    """The payment provider rejected or failed a charge."""


def charge_with_retry(gateway, amount, attempts=MAX_ATTEMPTS):
    """Charge a payment gateway, retrying transient failures with backoff."""
    for attempt in range(1, attempts + 1):
        try:
            return gateway.charge(amount)
        except PaymentError:
            if attempt == attempts:
                raise
            time.sleep(0.1 * attempt)
    return None

files.shop/pricing.py:
"""Cart pricing: subtotal, discounts, and tax."""

from shop.discounts import apply_discount_code
from shop.tax import tax_for_region


def subtotal(items):
    """Sum of item price times quantity."""
    return sum(item["price"] * item["quantity"] for item in items)


def cart_total(items, region, discount_code=None):
    """Final amount charged for a cart: discounted subtotal plus regional tax."""
    amount = subtotal(items)
    if discount_code:
        amount = apply_discount_code(amount, discount_code)
    return round(amount + tax_for_region(amount, region), 2)

files.shop/tax.py:
"""Regional sales tax."""

TAX_RATES = {"us": 0.07, "eu": 0.20, "uk": 0.20}


def tax_for_region(amount, region):
    """Sales tax owed on an amount for a shipping region."""
    rate = TAX_RATES.get(region.lower())
    if rate is None:
        raise KeyError(f"no tax rate for region {region}")
    return amount * rate
